package com.smartclinic.service; import com.smartclinic.model.Doctor; import com.smartclinic.repository.DoctorRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class DoctorService { private final DoctorRepository repo; public DoctorService(DoctorRepository r){repo=r;} public List<Doctor> available(String specialty){return specialty==null||specialty.isBlank()?repo.findAll():repo.findBySpecialtyIgnoreCase(specialty);} public Map<String,Object> login(String email,String password){Doctor d=repo.findByEmail(email).filter(x->x.getPassword().equals(password)).orElseThrow(()->new IllegalArgumentException("Неверные данные врача")); return Map.of("doctorId",d.getId(),"name",d.getName());} }
